import{_ as i,o as s,c as a,a2 as o}from"./chunks/framework.DdtnLau3.js";const h=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/quick-start.md","filePath":"zh/guide/quick-start.md"}'),t={name:"zh/guide/quick-start.md"};function r(n,e,p,k,c,d){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><h2 id="一键启动-piwork" tabindex="-1">一键启动 Piwork <a class="header-anchor" href="#一键启动-piwork" aria-label="Permalink to &quot;一键启动 Piwork&quot;">​</a></h2><p>Linux x86-64、rootful Docker Engine 28+。运行一个容器即可提供工作台、管理和首次设置，无需环境变量或客户端 CLI：</p><p>本版固定镜像包含直接访问与网页配置流程。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> piwork-core-quickstart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unless-stopped</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --stop-timeout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=bind,src=/var/run/docker.sock,dst=/var/run/docker.sock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/piwork/quickstart/core:/var/lib/piwork/quickstart/core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    docker.io/pphboy/piwork-core:0.0.9-0901cf119dc1-0e1261f05b9d</span></span></code></pre></div><p>在本机或另一台电脑直接打开 <code>http://服务器IP:17891</code>，使用服务器实际 IP。空安装会显示创建管理员；已有账号时正常登录，无需终端授权链接。</p><p>浏览器创建管理员时输入密码及确认密码，随后正常登录进入 Admin 的 <strong>Quick setup</strong>（<code>/admin/setup</code>）。按两步引导填写模型 ID、API 类型、Base URL 和 API Key，或选择已保存模型，点击 <strong>Save and continue</strong>，顺序保存模型并绑定 CoreRuntime。准备页面会自动更新；全部依赖显示 Ready 后，点击 <strong>Open workbench</strong> 进入 Piwork。Agent 镜像随服务端版本内置并自动使用，无需也不能手填、选择或高级覆盖。模型 Test 是显式可选操作；保存不自动调用模型。打开工作台创建 Work，然后聊天、管理文件或打开 Service。后续从 Admin <strong>Overview → Quick setup</strong> 返回配置；顶栏 <strong>Workbench</strong> 可随时返回工作台，准备区的完成按钮仍需等待全部 Ready。已保存的账号、模型和 Work 在重启后保留。</p><p>一键启动在同一进程运行两个独立 HTTP 服务：ControlPlane 默认 <code>0.0.0.0:17891</code>，Core 默认 <code>127.0.0.1:17871</code>。浏览器通过实际局域网 IP 的 17891 使用全部 UI、文件、事件及 <code>/services/&lt;workId&gt;/&lt;serviceId&gt;/&lt;port&gt;/</code>，无需域名或额外 Service 端口。后端与 CLI/operator 直连 Core；远程或 bridge CLI 需显式配置 <code>--core-listen 0.0.0.0:17871</code>（或可达网卡）并放行相应网络，不能把 loopback 当成容器可达。7172 保留为容器可达的内部 Agent mTLS RPC，不是浏览器入口。用户 Service 不发布宿主端口。HTTPS 反向代理须转发同一 origin 的全部路径、SSE 与 WebSocket；Core TLS 如有需要由受信终止入口提供。</p><p>托管 Service 与工作台同源，须视为可信应用；其脚本可使用当前用户的 UI 权限。应用须支持动态 Service URL 前缀；旧根路径应用不会自动改写源码、镜像或包。Service 支持响应 Cookie 的服务端登录、Basic/Bearer、HTTP、SSE 和 WebSocket。响应 Cookie 按浏览器会话及 Service 保存在服务器，Secure Cookie 仅通过 HTTPS 入口发送。依赖 document.cookie/Cookie Store 读写（如脚本读取 CSRF Cookie）的应用不保证透明兼容；脚本写入浏览器 Cookie 也不保证同 IP 跨 Service 隔离，且不会转发上游。不支持硬编码 .work URL、跨站 SSO 或上游 HTTPS 的透明适配。应用 CSP/X-Frame-Options 保留；禁止嵌入时使用新标签页。</p><p>可选 <a href="/piwork/piwork/install/0.0.9-0901cf119dc1-0e1261f05b9d/docker-compose.yml">Compose</a>（2.24+）和 <a href="https://github.com/pphboy/piwork/blob/main/examples/single-host/README.zh-CN.md" target="_blank" rel="noreferrer">单机示例</a> 同样直接进入网页；CLI 是高级可选工具。运行与恢复见 <a href="/piwork/zh/guide/installation.html#terminal-operations">安装手册</a>。</p><details><summary>构建并使用原生 Linux 应用</summary><p>Docker 镜像已包含统一入口。如需原生运行，先<a href="/piwork/zh/guide/source-installation.html">构建当前源码</a>，再从仓库根目录启动 Linux 程序；构建后的可执行文件也可在源码目录外使用：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./dist/go/piwork</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><p>默认数据目录为用户配置目录下 <code>piwork/server</code>，监听 <code>0.0.0.0:17891</code>；使用终端给出的实际 IP 链接。<code>--data-dir</code>、<code>--listen</code>、<code>--public-origin</code>、<code>--core-listen</code> 和 TLS 参数见 <code>--help</code>。</p><p>直接打开实际 IP 地址创建管理员并正常登录，无需额外链接校验。Agent 镜像随服务端版本内置并自动使用，不提供手填或覆盖；网页创建管理员后配置模型。</p><p>使用自定义数据目录时保留相同的 <code>--data-dir</code>。退出主程序会按 Core 关闭契约停止受管 Work；关闭网页不会。</p><p>同机 ControlPlane 已占用 17891 时，独立 Desktop 使用 <code>--port 17901</code>；不会自动换端口。CLI 默认连接 Core <code>http://127.0.0.1:17871</code>，显式地址和已有凭据优先，旧地址不会自动迁移。当前源码构建的独立客户端使用 <code>piwork-cli desktop --no-open</code> 启动，在本机浏览器打开 <code>http://desktop.localhost:17891/</code>（自定义端口以输出为准）。普通浏览器会话自动建立；已有 CLI 登录会直接复用，否则正常登录。<code>piwork-cli desktop open --no-open</code> 仅是可选的地址查询，不签发授权；刷新、新浏览器或清 Cookie 均可直接使用相同地址。CLI 容器须发布本机回环端口并保留状态卷，在宿主机浏览器打开输出的地址，无需 <code>docker exec ... desktop open</code>。Desktop 与 CLI 共享 Core 凭据；退出登录会清理共享登录，关闭网页不停止 Work。</p><p><code>piwork-cli</code> 保留独立 Windows/Linux 命令行与本机 Desktop；<code>piwork-console</code> 是独立管理入口，不属于默认启动依赖。历史 <a href="https://github.com/pphboy/piwork/releases/download/v0.0.7/piwork-linux-amd64-0.0.7.tar.gz" target="_blank" rel="noreferrer">0.0.7 Linux 发布包</a> 与 <a href="https://github.com/pphboy/piwork/releases/download/v0.0.5/piwork-cli-windows-amd64-0.0.5.exe" target="_blank" rel="noreferrer">实验性 Windows CLI 0.0.5</a> 不包含统一服务端入口。</p></details>`,11)])])}const C=i(t,[["render",r]]);export{h as __pageData,C as default};
